    // [kdf-a arx]
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseA(pNonce * 0xE0A42E7C42F7B0A3ULL + 0xD3554D7F47B0FFC9ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseA(pNonce * 0x84F9EC62652DFC1FULL + 0xE42C731092595FBAULL);
    [[maybe_unused]] const std::uint64_t aNonceWordC = TwistMix64::DiffuseB(pNonce * 0x81723A80F27445F5ULL + 0xF4AF342C80E66260ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordD = TwistMix64::DiffuseC(pNonce * 0x8ED5A66CBD404C4BULL + 0xBC7CB1BF607289CDULL);
    [[maybe_unused]] const std::uint64_t aNonceWordE = TwistMix64::DiffuseC(pNonce * 0xA2F822CDDA25BF15ULL + 0xF82485CEC3C37F67ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordF = TwistMix64::DiffuseA(pNonce * 0xE38CA3FCE42AA771ULL + 0xB731592C5636C8A7ULL);
