            aOrbiterI = ((aWandererG + RotL64(aPrevious, 58U)) + RotL64(aCarry, 27U)) + 0xEFA5E5C1872A5DE4ULL;
            aOrbiterB = (aWandererI + RotL64(aIngress, 39U)) + 0x72CE4B0F19AF3627ULL;
            aOrbiterC = (aWandererK + RotL64(aScatter, 13U)) + 0xE213376A590B90FCULL;
            aOrbiterG = ((aWandererF + RotL64(aPrevious, 51U)) + 0x4E322622EBBE1314ULL) + aOASaltD[(((511U - aIndex) + 157U)) & S_SALT1];
            aOrbiterJ = ((aWandererE + RotL64(aCross, 30U)) + 0xB1B743CD43431C43ULL) + aOASaltG[((aIndex + 234U)) & S_SALT1];
