            aOrbiterK = ((aOrbiterK + aOrbiterJ) + 0x5687BE6B052F2EB3ULL) + aNonceWordF;
            aOrbiterF = ((aOrbiterF ^ aOrbiterK) ^ 0x8797CE8C793F3F4FULL) ^ aOUSaltA[(((511U - aIndex) + 241U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0xBAA22154D05BD5CDULL), 13U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterD) + 0x51C21FD380F5E718ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterJ) ^ 0x862A7F0E5C6B5C3DULL) ^ aOUSaltC[((aIndex + 288U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x491E5B28D3CD1109ULL), 39U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x613EEE817C6DA207ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterB) ^ 0x04F283EB3620B60AULL) ^ aOUSaltF[((aIndex + 491U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x149318104D90B4B9ULL), 51U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterA) + 0x4C1AD87C35412739ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterG) ^ 0x2929706CE3EAB54CULL) ^ aOUSaltD[((aIndex + 83U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x74689CF48508234FULL), 35U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterH) + 0xBF2A18C7024AF109ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterF) ^ 0x42F15493DFA4C3A0ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xDE6974C97DF6D2B7ULL), 41U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterI) + 0x20AF8693C21F6DE3ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0x44627E34703652F0ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x37F5F85837EAE119ULL), 29U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterF) + 0x584F6D077446C8F9ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterE) ^ 0xE0C53C7547D95255ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x3AB565744A207B97ULL), 19U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterE) + 0x4A025D070D813ED3ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterD) ^ 0xEFE73214620A86A3ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x069EEC0CA7C55759ULL), 27U);
            //
            aIngress = RotL64(aOrbiterG, 13U) ^ aOrbiterC;
