            aOrbiterD = (aOrbiterD + aOrbiterJ) + 0xB3D986C87AC47685ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterD) ^ 0x9AF231AA1B19F22DULL) ^ aOUSaltE[((aIndex + 148U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x434817C9CAB7D377ULL), 53U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterH) + 0xFBABB4562B2088B4ULL;
