            aOrbiterA = (aWandererD + RotL64(aScatter, 19U)) + 0xDB56374F6DE836A3ULL;
            aOrbiterF = ((aWandererA + RotL64(aCross, 57U)) + 0x1D206097C184F81DULL) + aOASaltB[((aIndex + 86U)) & S_SALT1];
            aOrbiterE = ((aWandererJ + RotL64(aIngress, 13U)) + 0x6C0614EF4DB1FA70ULL) + aOASaltD[(((511U - aIndex) + 149U)) & S_SALT1];
            //
