            aOrbiterA = RotL64((aOrbiterA * 0x1191428898FE68A5ULL), 29U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterF) + 0x92E150714216465CULL) + aOUSaltH[((aIndex + 160U)) & S_SALT1];
