            aCross = TwistMix64::DiffuseC((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aCarry, 44U) ^ RotL64(aIngress, 23U)) + (RotL64(aPrevious, 57U) + RotL64(aCross, 11U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterK = ((aWandererD + RotL64(aPrevious, 35U)) + RotL64(aCarry, 41U)) + 0xB94EFD82D0A814CDULL;
            aOrbiterG = ((aWandererG + RotL64(aScatter, 60U)) + RotL64(aCarry, 23U)) + 0xBF144F9CF2FEFA61ULL;
            aOrbiterA = ((aWandererK + RotL64(aIngress, 47U)) + 0xB35E4A597F079369ULL) + aOASaltB[((aIndex + 69U)) & S_SALT1];
            aOrbiterE = (((aWandererI + RotL64(aCross, 29U)) + RotL64(aCarry, 11U)) + 0xE466F77F31EBEAF4ULL) + aOASaltG[(((511U - aIndex) + 120U)) & S_SALT1];
