            aOrbiterD = (aWandererB + RotL64(aIngress, 6U)) + 0x5E92E36A87A5FC06ULL;
            aOrbiterI = (aWandererJ + RotL64(aCross, 39U)) + 0xDD3282C412C121CAULL;
            aOrbiterC = ((aWandererH + RotL64(aScatter, 11U)) + 0x8ABD13C35316B5A7ULL) + aOASaltC[((aIndex + 89U)) & S_SALT1];
            aOrbiterH = ((aWandererE + RotL64(aCross, 51U)) + 0xDDEB89B82678F4AEULL) + aOASaltH[((aIndex + 269U)) & S_SALT1];
            //
