            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0xC8C1C92A3430746DULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterA) ^ 0xB017579CE76AAAE2ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x9B34669CADB11C0DULL), 23U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterI) + 0x5E3B4F341C18EB3DULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0xAE933C64BDF30A68ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x21FD98B21589A5A1ULL), 57U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterG) + 0x1E0C0C2762518F0DULL) + aOUSaltH[(((511U - aIndex) + 161U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterF) ^ 0xE4A8FC3EEB261785ULL) ^ aOUSaltB[((aIndex + 188U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x40E29DB4DE97C05DULL), 51U);
            //
