            aWandererJ = aWandererJ ^ (((RotL64(aCross, 24U) + RotL64(aOrbiterH, 58U)) + aOrbiterA) + aWUSaltB[((aIndex + 411U)) & S_SALT1]);
            aWandererB = aWandererB + ((RotL64(aScatter, 37U) + aOrbiterC) + RotL64(aOrbiterA, 5U));
            aWandererI = aWandererI ^ ((RotL64(aIngress, 19U) + RotL64(aOrbiterJ, 41U)) + aOrbiterA);
            //
