            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterD = ((aWandererD + RotL64(aPrevious, 37U)) + 0xDE1D65CB499F55BAULL) + aOASaltE[(((511U - aIndex) + 348U)) & S_SALT1];
            aOrbiterB = ((aWandererB + RotL64(aScatter, 11U)) + RotL64(aCarry, 51U)) + 0xF5ED1DA445FB98DAULL;
            aOrbiterC = (aWandererE + RotL64(aIngress, 40U)) + 0x1E539C05296FA60EULL;
            aOrbiterH = ((aWandererF + RotL64(aCross, 29U)) + RotL64(aCarry, 11U)) + 0x590B4506BBC27DFBULL;
            aOrbiterK = (aWandererC + RotL64(aIngress, 23U)) + 0x646B35E40FDB7E52ULL;
            aOrbiterI = (aWandererK + RotL64(aScatter, 35U)) + 0x933B9B2647BDEE2FULL;
            aOrbiterA = ((aWandererJ + RotL64(aCross, 4U)) + 0xBD1DF209CB904A1FULL) + aOASaltF[(((511U - aIndex) + 261U)) & S_SALT1];
            aOrbiterJ = ((aWandererI + RotL64(aPrevious, 21U)) + 0x793647DB75E5809FULL) + aOASaltH[((aIndex + 113U)) & S_SALT1];
            aOrbiterF = ((aWandererA + RotL64(aIngress, 13U)) + 0xE3F2F851E7398B50ULL) + aOASaltA[((aIndex + 488U)) & S_SALT1];
            aOrbiterE = (((aWandererH + RotL64(aPrevious, 53U)) + RotL64(aCarry, 47U)) + 0x54C0450AAC3CC457ULL) + aOASaltC[(((511U - aIndex) + 267U)) & S_SALT1];
            aOrbiterG = (aWandererG + RotL64(aScatter, 57U)) + 0x33CD7AF1B6738707ULL;
            //
            aOrbiterD = ((aOrbiterD + aOrbiterB) + 0xC47E95D0D3826494ULL) + aOUSaltH[((aIndex + 392U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterD) ^ 0x13C0C23EBC323416ULL) ^ aOUSaltA[(((511U - aIndex) + 306U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xB9EB3C8FA046BDE3ULL), 57U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterK) + 0xF4E9604743A415E4ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterH) ^ 0x9EF84773509BDF78ULL) ^ aOUSaltC[((aIndex + 501U)) & S_SALT1];
