            aOrbiterC = (aOrbiterC + aOrbiterF) + 0x111098CA895D3F61ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterC) ^ 0xF56332F68A648F1DULL;
            aOrbiterA = RotL64((aOrbiterA * 0xB17D013D48BE9485ULL), 3U);
