            aOrbiterI = ((aWandererC + RotL64(aIngress, 3U)) + 0xB0697CF4895E8B10ULL) + aOASaltB[((aIndex + 165U)) & S_SALT1];
            aOrbiterE = (((aWandererF + RotL64(aCross, 36U)) + RotL64(aCarry, 35U)) + 0x11A26CCEAA02FD85ULL) + aOASaltD[(((511U - aIndex) + 147U)) & S_SALT1];
            aOrbiterD = (((aWandererD + RotL64(aIngress, 43U)) + RotL64(aCarry, 57U)) + 0x85F9DEB0F3696025ULL) + aOASaltF[(((511U - aIndex) + 173U)) & S_SALT1];
            aOrbiterC = (aWandererK + RotL64(aScatter, 27U)) + 0x27B7432B10235268ULL;
            aOrbiterJ = (aWandererJ + RotL64(aCross, 57U)) + 0x4AA3E44639B57B73ULL;
            //
            aOrbiterH = ((aOrbiterH + aOrbiterF) + 0x028E894E8A39C572ULL) + aOUSaltG[((aIndex + 457U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterH) ^ 0xFA217AB8370F5DA9ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x9484C9B90B940F79ULL), 13U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterI) + 0xEC8C4BC4D0D45D36ULL) + aOUSaltF[(((511U - aIndex) + 286U)) & S_SALT1];
