            aOrbiterD = RotL64((aOrbiterD * 0x0A39A574AE85EF5FULL), 41U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterC) + 0x6FCD3270E5C38926ULL) + aOUSaltB[((aIndex + 450U)) & S_SALT1];
