            aOrbiterE = RotL64((aOrbiterE * 0xED5C16581D5AF1AFULL), 53U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterJ) + 0x9E7B9671C42C986EULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0xC964FAA5D4FA8F75ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x6979264D4ED6EC77ULL), 19U);
            //
            aIngress = aOrbiterE ^ RotL64(aOrbiterD, 41U);
