            aIngress = TwistMix64::DiffuseC((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 11120U)) & S_BLOCK1], 37U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 15139U)) & S_BLOCK1], 28U));
            aCross ^= (RotL64(aShadowLaneD[((S_BLOCK1 - aIndex + 13605U)) & S_BLOCK1], 5U) ^ RotL64(aShadowLaneA[((aIndex + 9829U)) & S_BLOCK1], 47U));
            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 57U) ^ RotL64(aCross, 5U)) + (RotL64(aCarry, 27U) + RotL64(aIngress, 42U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterG = ((aWandererF + RotL64(aIngress, 39U)) + 0xD79327D465169C60ULL) + aOASaltA[(((511U - aIndex) + 109U)) & S_SALT1];
            aOrbiterJ = (aWandererD + RotL64(aPrevious, 5U)) + 0x6029101A21D47793ULL;
            aOrbiterK = ((aWandererB + RotL64(aCross, 19U)) + RotL64(aCarry, 53U)) + 0x7DE20A57DD158DE4ULL;
            aOrbiterE = (aWandererC + RotL64(aScatter, 13U)) + 0x32821A9CE2AF27B4ULL;
            aOrbiterA = ((aWandererK + RotL64(aIngress, 57U)) + RotL64(aCarry, 41U)) + 0x3E57C788FBC27C23ULL;
            aOrbiterH = (((aWandererE + RotL64(aScatter, 47U)) + RotL64(aCarry, 13U)) + 0x2AA49EF0BE25C69BULL) + aOASaltH[((aIndex + 325U)) & S_SALT1];
            aOrbiterD = ((aWandererG + RotL64(aCross, 30U)) + 0x3A4918CCEE9649F2ULL) + aOASaltB[(((511U - aIndex) + 399U)) & S_SALT1];
            //
            aOrbiterG = (aOrbiterG + aOrbiterJ) + 0x5EC5017DC629AD29ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterG) ^ 0x809918B159A9B68FULL) ^ aOUSaltE[(((511U - aIndex) + 249U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xBC303995F2909AD9ULL), 37U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0x588A22A17A5153B7ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0x5FDA892FDEF215A3ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x9A569F40EDAFCF0BULL), 27U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterH) + 0x3C9493335E53A481ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterA) ^ 0x8CB8EAAE0C1657E9ULL) ^ aOUSaltC[((aIndex + 17U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xF1F876798C4EE4F3ULL), 19U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterA) + 0xB5B4B7365914E674ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterK) ^ 0xBF966D051AE455C7ULL) ^ aOUSaltF[((aIndex + 184U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x7BCBB8F91331CD8BULL), 43U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0x6784E2292E17CF91ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0xFBCEC8A2BF7B14E5ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x149798AFB1623051ULL), 57U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterK) + 0xB3437436D892F8AEULL) + aOUSaltG[(((511U - aIndex) + 174U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterE) ^ 0xBE64798AE8962FD6ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xA98AF70D2203D123ULL), 5U);
